-- M9.3: the baseline builder. NIST's macOS Security Compliance Project, DISA's Intune policy
-- package (settings-catalog exports per STIG) and the GPO package's checklists join the Register.

INSERT OR IGNORE INTO sources (id, name, kind, group_name, url, format, schedule, enabled, licence, attribution, notes) VALUES
('nist-mscp', 'NIST macOS Security Compliance Project', 'requirement-set', 'standards', 'https://github.com/usnistgov/macos_security', 'yaml-zip', 'daily', 1, 'NIST; public domain in the United States (see the repository LICENSE)', 'Rules from the macOS Security Compliance Project (NIST, NASA, DISA, LANL).', 'One branch per macOS release (tahoe, sequoia; a watchlist entry of kind "baseline" written "mscp: <branch>" follows others). Every rule with its check, fix, configuration-profile payload keys, severity and its SP 800-53 r5, 800-171 r3, CCI, STIG and CIS references; which baselines (800-53 High, DISA STIG, CIS Level 1 and 2, CMMC) list it. The branch''s current commit is read from the GitHub API, so an unchanged branch costs one small request.'),
('disa-intune', 'DISA STIG Intune policy package', 'setting-set', 'standards', 'https://www.cyber.mil/stigs/gpo/', 'intune-zip', 'daily', 1, 'US Government work, public domain', NULL, 'The settings-catalog policies DISA ships for its STIGs (Windows 11 and 10, Edge, Chrome, Defender, the firewall, Microsoft 365 Apps), one setting per row with its value, diffed package by package. Found through the STIG library listing ("Intune Policy - <month>"), so an unchanged package costs one small request.'),
('disa-gpo', 'DISA STIG GPO package checklists', 'requirement-set', 'standards', 'https://www.cyber.mil/stigs/gpo/', 'ckl-zip', 'daily', 1, 'US Government work, public domain', NULL, 'The checklists in DISA''s GPO package: for every rule of each STIG it provides policies for, DISA''s own verdict on whether its GPO and Intune policies set it or it is outside their scope. The GPO backups themselves are not parsed. Found through the STIG library listing ("Group Policy Objects (GPOs) - <month>").');
